        html.dark{color-scheme:dark;--page:#0f172a;--surface:#18181b;--soft:#27272a;--ink:#f8fafc;--muted:#a1a1aa;--line:#3f3f46}html.light{color-scheme:light;--page:#f8fafc;--surface:#fff;--soft:#f8fafc;--ink:#111827;--muted:#667085;--line:#e4e7ec}
        *{box-sizing:border-box} body{min-height:100dvh;margin:0;display:grid;place-items:center;padding:clamp(1rem,4vw,2rem);background:var(--page);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.card{width:100%;max-width:34rem;padding:1.25rem;background:var(--surface);border:1px solid var(--line);border-radius:1rem;box-shadow:0 1rem 2.5rem rgb(15 23 42 / .12)}.brand{display:flex;align-items:center;justify-content:space-between;gap:.75rem;padding-bottom:1rem;margin-bottom:1rem;border-bottom:1px solid var(--line)}.brand img{width:auto;height:2.25rem;max-width:8rem;object-fit:contain}.brand span{color:var(--muted);font-size:.75rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase}h1{margin:0;font-size:1.25rem;line-height:1.3}.sub{margin:.25rem 0 1rem;color:var(--muted);font-size:.875rem;line-height:1.45}.lectura{display:flex;gap:.65rem;align-items:flex-start;padding:.8rem .875rem;margin:0 0 .85rem;border:1px solid #86efac;border-radius:.75rem;background:#f0fdf4;color:#166534}.lectura svg{width:1.35rem;height:1.35rem;flex:0 0 auto}.lectura strong{display:block;font-size:.875rem}.lectura span{display:block;margin-top:.12rem;font-size:.8125rem;line-height:1.4;color:#15803d}.turno,.ultima,.estado,.errores{padding:.875rem;border:1px solid var(--line);border-radius:.75rem;font-size:.875rem;line-height:1.45}.turno,.ultima{margin-bottom:.75rem;background:var(--soft);color:var(--muted)}.turno strong,.ultima strong{color:var(--ink)}.estado{margin:1rem 0;background:color-mix(in srgb,var(--primary) 8%,var(--surface));border-color:color-mix(in srgb,var(--primary) 33%,var(--line))}.estado strong{display:block;margin-bottom:.2rem;color:var(--primary);font-size:.9375rem}.estado span{color:var(--muted)}.errores{margin-bottom:.85rem;background:#fef2f2;border-color:#fecaca;color:#b91c1c}.acciones{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.625rem;margin-top:1rem}.accion-form{margin:0}.marca{position:relative;display:flex;min-height:6.25rem;width:100%;flex-direction:column;align-items:center;justify-content:center;gap:.25rem;padding:.8rem;border:1px solid transparent;border-radius:.75rem;color:#fff;font:inherit;font-size:.9rem;font-weight:800;cursor:pointer;box-shadow:0 .25rem .65rem rgb(15 23 42 / .12);transition:transform .15s ease,filter .15s ease}.marca small{max-width:12rem;font-size:.72rem;font-weight:500;line-height:1.3;opacity:.93;text-align:center}.marca:active{transform:scale(.98)}.marca:hover:not(:disabled){filter:brightness(.96)}.marca:disabled{cursor:not-allowed;box-shadow:none;color:var(--muted);background:var(--soft);border-color:var(--line)}.marca:disabled small{opacity:1}.codigo{position:absolute;top:.45rem;left:.5rem;display:grid;place-items:center;min-width:1.4rem;height:1.4rem;padding:0 .3rem;border:1px solid currentColor;border-radius:.4rem;color:currentColor;font-size:.68rem;font-weight:800;line-height:1}.btn-entrada{background:#16a34a}.btn-salida{background:#dc2626}.btn-salida_refrigerio{background:#d97706}.btn-regreso_refrigerio{background:#2563eb}.completo{padding:.35rem .5rem;text-align:center;color:#15803d;font-size:.875rem}.links{display:flex;justify-content:space-between;gap:.75rem;margin-top:1.25rem}.links a,.links button{display:inline-flex;align-items:center;gap:.35rem;padding:0;border:0;background:none;color:var(--muted);font:inherit;font-size:.8125rem;cursor:pointer;text-decoration:none}@media(max-width:640px){body{display:block;padding:0}.card{min-height:100dvh;max-width:none;padding:1.25rem 1rem calc(1.25rem + env(safe-area-inset-bottom));border:0;border-radius:0;box-shadow:none}.acciones{grid-template-columns:1fr}.marca{min-height:4.85rem}.links{margin-top:1rem}}
