<script>document.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.target.matches('input,textarea,select,button'))return;const boton=document.querySelector(`[data-codigo-marcacion="${event.key}"]:not(:disabled)`);if(boton){event.preventDefault();boton.click();}});</script>
